import random
import time
from typing import List

# This generator creates valid file contents for wxFileName-based fuzzers.
# Keep size <= 4096 bytes and avoid embedding NULs in the source code literal.
# Any NULs needed in the output are produced programmatically via bytes([...]).

_MAX_SIZE = 4096

_TEXT_LINES = [
    b"Hello, world!\n",
    b"The quick brown fox jumps over the lazy dog.\n",
    b"key=value\n",
    b"#!/bin/sh\n",
    b"#include <stdio.h>\nint main(){return 0;}\n",
]

# Build some UTF-8 code point ranges for variety
def _rand_ascii_run(rng: random.Random, lo=32, hi=126, length_range=(5, 40)) -> str:
    return ''.join(chr(rng.randrange(lo, hi + 1)) for _ in range(rng.randint(*length_range)))

def _utf8_block(rng: random.Random, target_len: int) -> bytes:
    pieces: List[str] = []
    while len(''.join(pieces).encode('utf-8')) < target_len:
        choice = rng.randrange(4)
        if choice == 0:
            pieces.append(_rand_ascii_run(rng))
        elif choice == 1:
            # Random BMP code point excluding surrogates
            cp = rng.randrange(0x20, 0xD7FF)
            pieces.append(chr(cp))
        elif choice == 2:
            # Supplementary plane (emoji etc.)
            cp = rng.randrange(0x1F300, 0x1FAFF)
            try:
                pieces.append(chr(cp))
            except ValueError:
                pass
        else:
            # Accented letters block
            base = [0x00E9, 0x00E8, 0x00F1, 0x00E4, 0x00FC, 0x00E7]
            pieces.append(''.join(chr(rng.choice(base)) for _ in range(rng.randint(3, 12))))
    s = ''.join(pieces)
    data = s.encode('utf-8', errors='strict')
    if len(data) > target_len:
        cut = target_len
        while cut > 0:
            try:
                data[:cut].decode('utf-8')
                data = data[:cut]
                break
            except UnicodeDecodeError:
                cut -= 1
        else:
            data = b"A" * min(target_len, 16)
    if rng.random() < 0.5 and (not data.endswith(b"\n")):
        data += b"\n"
    return data

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _binary_block(rng: random.Random, n: int) -> bytes:
    parts: List[bytes] = []
    # Header magics constructed without literal NULs in source
    magics = [
        bytes([0x7F, 0x45, 0x4C, 0x46]),               # \x7FELF
        bytes([0x4D, 0x5A, 0x90, 0x00]),               # MZ\x90\x00
        bytes([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),  # PNG
        bytes([0x50, 0x4B, 0x03, 0x04]),               # PK\x03\x04
        b"%PDF-1.",
    ]
    if rng.random() < 0.7:
        parts.append(rng.choice(magics))
    remaining = max(0, n - sum(len(p) for p in parts))
    while remaining > 0:
        kind = rng.randrange(4)
        if kind == 0:
            chunk = _rand_bytes(rng, min(remaining, rng.randint(16, 128)))
        elif kind == 1:
            # NUL run
            chunk = bytes([0]) * min(remaining, rng.randint(8, 64))
        elif kind == 2:
            # Repeating pattern
            pat = bytes([rng.randrange(256) for _ in range(4)])
            reps = min(max(1, remaining // len(pat)), rng.randint(2, 16))
            chunk = (pat * reps)[:remaining]
        else:
            s = f"Size:{remaining} Time:{int(time.time())}\n".encode()
            chunk = s[:remaining]
        parts.append(chunk)
        remaining = max(0, n - sum(len(p) for p in parts))
    return b"".join(parts)

def _text_file(rng: random.Random, target_len: int) -> bytes:
    lines = []
    if rng.random() < 0.3:
        lines.append(b"#!/usr/bin/env python3\n")
    k = rng.randint(1, len(_TEXT_LINES))
    lines.extend(rng.sample(_TEXT_LINES, k=k))
    for _ in range(rng.randint(3, 20)):
        ln = _rand_ascii_run(rng, length_range=(5, 80)).encode() + b"\n"
        lines.append(ln)
    data = b"".join(lines)
    if len(data) < target_len:
        pad = b"# padding\n"
        need = target_len - len(data)
        reps = need // len(pad) + 1
        data += pad * reps
    return data[:target_len]

def _compose(rng: random.Random) -> bytes:
    choice = rng.randrange(5)
    if choice == 0:
        size = rng.randint(256, min(2048, _MAX_SIZE))
        return _utf8_block(rng, size)
    elif choice == 1:
        size = rng.randint(128, _MAX_SIZE)
        return _binary_block(rng, size)
    elif choice == 2:
        size = rng.randint(32, 512)
        return _text_file(rng, size)
    elif choice == 3:
        size = rng.randint(1024, _MAX_SIZE)
        prefix = _text_file(rng, rng.randint(128, 512))
        rest_len = max(0, size - len(prefix))
        suffix = _utf8_block(rng, rest_len) if rest_len > 0 else b""
        return (prefix + suffix)[:size]
    else:
        # Archive-like headers without literal NULs in source
        headers = [
            bytes([0x50, 0x4B, 0x03, 0x04, 0x14, 0x00]),  # ZIP local header
            b"%PDF-1.7\n",
            bytes([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
        ]
        hdr = rng.choice(headers)
        rest = _rand_bytes(rng, rng.randint(64, _MAX_SIZE - len(hdr)))
        return (hdr + rest)[:_MAX_SIZE]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    data = _compose(rng)
    if not data:
        data = b"A\n"
    if len(data) > _MAX_SIZE:
        data = data[:_MAX_SIZE]
    return data
